const Q=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),safeUrl=u=>{try{const x=new URL(u);return /^https?:$/.test(x.protocol)?x.href:''}catch{return ''}},palette=['var(--blue)','var(--orange)','var(--teal)','var(--purple)','var(--red)','#7193a5'];
let stored;try{stored=JSON.parse(localStorage.getItem('packet-research-v3')||'{}')}catch{stored={}}let old;try{old=JSON.parse(localStorage.getItem('aerointel-v1')||'{}')}catch{old={}}
const S={theme:'dark',collapsed:innerWidth<800,view:'canvas',board:'overview',query:'',company:'All companies',evidence:'All evidence',libraryStatus:'All statuses',libraryCategory:'All topics',libraryPage:0,dataset:'operators',layouts:{},imports:{},notes:{},checks:old.checks||{},...stored};S.edit??=true;let draft=null,editId=null,lastFocus=null,dragId=null,toastTimer;
const meta={market:{label:'Industry time series',desc:'IBISWorld OD6309 · PDF p.43 / printed p.40. US food-delivery industry, not drone TAM. Revenue and wages in USD billions.',fields:['year','revenue','employment','enterprises','wages','period'],numeric:['year','revenue','employment','enterprises','wages']},segments:{label:'Market segmentation',desc:'IBISWorld 2026 shares: platform revenue, service type and household-income segment. General industry, not drone shares.',fields:['name','category','share','revenue','year'],numeric:['share','revenue','year']},operators:{label:'Operator certification',desc:'Eight brand profiles mapped to their legal operating entities. Historical milestones are separate from present mission authority.',fields:['name','focus','year','holder','milestone','status'],numeric:['year']},capabilities:{label:'Aircraft capability claims',desc:'Company statements, with aircraft and development status preserved. Range units and approval scope are not normalized.',fields:['company','aircraft','payload_lb','range_miles','range_basis','status'],numeric:['payload_lb','range_miles']},relationships:{label:'Partnership relationships',desc:'Dated official announcements. A graph edge does not confirm current availability or commercial terms.',fields:['company','partner','category','date','status'],numeric:[]},regulations:{label:'Flight-readiness tasks',desc:'Planning tasks linked to agency sources. Recorded reviews are not flight clearance.',fields:['name','category','jurisdiction','status'],numeric:[]},partners:{label:'Seattle property prospects',desc:'Official property and tenant pages. These are candidates, not confirmed partners or approved sites.',fields:['name','category','location','property','status'],numeric:[]},articles:{label:'Research document catalogue',desc:'Public website and FAA indexes plus the supplied report. Reviewed summaries, metadata-indexed pages and linked PDFs are labeled separately.',fields:['name','company','category','source_type','status','published'],numeric:[]},coverage:{label:'Research coverage',desc:'Catalogue counts indicate indexed documents, not company scale or operational quality. Flytrex extraction is limited.',fields:['name','records','reviewed','status'],numeric:['records','reviewed']}};
const labels={revenue:'Revenue ($B)',employment:'Employment',enterprises:'Enterprises',wages:'Wages ($B)',payload_lb:'Payload (lb)',range_miles:'Published range (mi)',share:'Revenue share (%)',year:'Year',name:'Name',company:'Company',source_type:'Source type',status:'Status',category:'Category',holder:'Legal operator',range_basis:'Range definition',published:'Publication date',records:'Indexed records',reviewed:'Reviewed records',period:'Period'};
const defaultLayouts={overview:[{id:'w1',title:'Food-delivery industry · history and outlook',dataset:'market',type:'line',x:'year',y:'revenue',agg:'sum',width:8,note:'Exact report series. Dashed portion is the 2027–2031 forecast. This is general industry revenue.'},{id:'w2',title:'Service mix · US food delivery, 2026',dataset:'segments',type:'donut',x:'name',y:'share',agg:'sum',filter:'Service mix',width:4},{id:'w3',title:'Published payload claims · aircraft specific',dataset:'capabilities',type:'bar',x:'name',y:'payload_lb',agg:'max',width:6,note:'Includes planned/design claims. Click an aircraft to inspect status and source. Missing values are not zero.'},{id:'w4',title:'Part 135 milestones · legal-entity map',dataset:'operators',type:'timeline',x:'name',y:'year',agg:'max',width:6},{id:'w5',title:'Delivery ecosystem · announced relationships',dataset:'relationships',type:'graph',x:'company',y:'count',agg:'count',width:8},{id:'w6',title:'Readiness tasks · by accountable domain',dataset:'regulations',type:'bar',x:'category',y:'count',agg:'count',width:4,note:'Task counts describe this planning checklist, not regulatory burden or permission to operate.'},{id:'w7',title:'Research coverage · indexed vs reviewed',dataset:'coverage',type:'bar',x:'name',y:'records',agg:'sum',width:6},{id:'w8',title:'Seattle access points · prospect register',dataset:'partners',type:'table',x:'category',y:'count',agg:'count',width:6}],operators:[{id:'o1',title:'Operator register · certificate holder and focus',dataset:'operators',type:'table',x:'name',y:'count',agg:'count',width:12},{id:'o2',title:'Aircraft claims · payload and range semantics',dataset:'capabilities',type:'table',x:'company',y:'count',agg:'count',width:8},{id:'o3',title:'Announcement evidence by company',dataset:'articles',type:'bar',x:'company',y:'count',agg:'count',width:4,filter:'Reviewed'},{id:'o4',title:'Commercial relationships',dataset:'relationships',type:'graph',x:'company',y:'count',agg:'count',width:12}],readiness:[{id:'r1',title:'Readiness register · evidence review status',dataset:'regulations',type:'table',x:'category',y:'count',agg:'count',width:8},{id:'r2',title:'Recorded reviews',dataset:'regulations',type:'donut',x:'status',y:'count',agg:'count',width:4},{id:'r3',title:'Official regulatory document catalogue',dataset:'articles',type:'list',x:'company',y:'count',agg:'count',width:8,filter:'Regulator'},{id:'r4',title:'Tasks by jurisdiction',dataset:'regulations',type:'bar',x:'jurisdiction',y:'count',agg:'count',width:4}],custom:[]};
const boardNames={overview:'Research overview',operators:'Operator landscape',readiness:'Flight readiness',custom:'My canvas',...(S.boardNames||{})};for(const [k,v]of Object.entries(defaultLayouts))S.layouts[k]??=structuredClone(v);
function persist(){try{localStorage.setItem('packet-research-v3',JSON.stringify({...S,boardNames}))}catch{toast('Browser storage is full. Export the analysis to preserve your changes.')}}
function allData(){return {...researchData,...S.imports}}
function dataFor(id){return (allData()[id]||[]).map(r=>id==='regulations'?{...r,status:S.checks[r.index]?'Review recorded':'Not reviewed'}:r)}
function datasetMeta(id){if(meta[id])return meta[id];const rows=S.imports[id]||[],fields=[...new Set(rows.flatMap(r=>Object.keys(r)))].filter(f=>!['id','source_url','source_type','evidence','locator'].includes(f));return {label:S.importNames?.[id]||id,desc:'User-imported structured research. Source claims require review.',fields,numeric:fields.filter(f=>rows.some(r=>typeof r[f]==='number'))}}
function rowsFor(w={}){let rows=dataFor(w.dataset||S.dataset),q=S.query.toLowerCase().trim();if(q)rows=rows.filter(r=>Object.values(r).join(' ').toLowerCase().includes(q));if(S.company!=='All companies'&&['articles','operators','capabilities','relationships','coverage'].includes(w.dataset))rows=rows.filter(r=>(r.company||r.name||'').toLowerCase().includes(S.company.toLowerCase())||(S.company==='Matternet'&&(r.company||'').includes('Matternet')));if(S.evidence!=='All evidence')rows=rows.filter(r=>r.source_type===S.evidence);if(w.filter)rows=rows.filter(r=>Object.values(r).join(' ').toLowerCase().includes(w.filter.toLowerCase()));return rows}
function groupRows(w,rows){const groups=new Map;for(const r of rows){let k=r[w.x];if(k===undefined||k===null||k==='')k='Not recorded';if(!groups.has(k))groups.set(k,[]);groups.get(k).push(r)}return [...groups].map(([key,rs])=>{let nums=rs.map(r=>r[w.y]).filter(v=>typeof v==='number'&&Number.isFinite(v));let value=w.agg==='count'||w.y==='count'?rs.length:nums.length?(w.agg==='avg'?nums.reduce((a,b)=>a+b,0)/nums.length:w.agg==='max'?Math.max(...nums):w.agg==='min'?Math.min(...nums):nums.reduce((a,b)=>a+b,0)):null;return {key,value,records:rs}}).filter(g=>g.value!==null)}
function fmt(n,field=''){if(n===null||n===undefined)return 'Not recorded';if(typeof n!=='number')return String(n);if(field==='year')return String(n);if(Math.abs(n)>=1e6)return(n/1e6).toFixed(1)+'M';if(Math.abs(n)>=1e3)return n.toLocaleString('en-US',{maximumFractionDigits:0});return n.toLocaleString('en-US',{maximumFractionDigits:field==='revenue'||field==='wages'?1:2})}
const recordAttrs=(ds,id)=>`data-record="${esc(ds)}:${esc(id)}"`;
function toast(msg){Q('#toast').textContent=msg;Q('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>Q('#toast').style.display='none',3200)}
function shell(){document.documentElement.dataset.theme=S.theme;const datasets=Object.keys(allData());Q('#app').innerHTML=`<nav class="rail" aria-label="Application controls"><div class="monogram" title="PacketIntelligence">P</div><button data-nav="canvas" class="${S.view==='canvas'?'active':''}" title="Analysis canvas" aria-label="Analysis canvas">▦</button><button data-nav="library" class="${S.view==='library'?'active':''}" title="Research library" aria-label="Research library">▤</button><button data-nav="datasets" class="${S.view==='datasets'?'active':''}" title="Data catalogue" aria-label="Data catalogue">⊞</button><button data-nav="lineage" class="${S.view==='lineage'?'active':''}" title="Data lineage" aria-label="Data lineage">⌘</button><button class="rail-bottom" data-toggle-sidebar title="Toggle sidebar" aria-label="Toggle sidebar">${S.collapsed?'»':'«'}</button></nav><aside class="explorer ${S.collapsed?'closed':''}" aria-label="Analysis explorer"><div class="explorer-head"><h1>PacketIntelligence</h1><small>RESEARCH & OPERATIONS ANALYSIS</small></div><div class="explorer-scroll"><div class="nav-section">Workspace</div><div class="tree"><button data-nav="canvas" class="${S.view==='canvas'?'active':''}">▦ <span>Analysis canvas</span></button><button data-nav="library" class="${S.view==='library'?'active':''}">▤ <span>Research library</span><span class="count">${dataFor('articles').length}</span></button><button data-nav="datasets" class="${S.view==='datasets'?'active':''}">⊞ <span>Data catalogue</span><span class="count">${datasets.length}</span></button><button data-nav="lineage" class="${S.view==='lineage'?'active':''}">⌘ <span>Sources & lineage</span></button></div><div class="nav-section">Object sets</div><div class="tree">${datasets.map(k=>`<button class="indent ${S.view==='datasets'&&S.dataset===k?'active':''}" data-dataset="${k}" draggable="true" data-drag-dataset="${k}"><span style="color:var(--blue)">▧</span>${esc(datasetMeta(k).label)}<span class="count">${dataFor(k).length}</span></button>`).join('')}</div><div class="nav-section">Add data</div><div class="tree"><button data-import>＋ Import CSV / JSON</button><button data-add-article>＋ Add research document</button></div></div><div class="explorer-foot"><div class="theme-label">APPEARANCE</div><div class="theme-swatches">${[['light','#e8edf1'],['dark','#263340'],['midnight','#151f33'],['packet','#b4432f']].map(([t,c])=>`<button data-theme="${t}" class="${S.theme===t?'active':''}" style="background:${c}" title="${t} theme" aria-label="${t} theme"></button>`).join('')}</div>Research snapshot · 25 Oct 2026<br>Layouts, notes and imports save locally.</div></aside><main class="workspace ${S.collapsed?'expanded':''}"><header class="appbar"><div class="breadcrumbs"><button class="icon-button" data-toggle-sidebar aria-label="Collapse or expand sidebar">☰</button><span>Research workspace</span><span>/</span><b>${S.view==='canvas'?'Drone delivery intelligence':S.view==='library'?'Research library':S.view==='lineage'?'Sources & lineage':'Data catalogue'}</b></div><div class="appbar-actions"><span class="saved">● Browser-local autosave</span><select id="theme-select" class="toolbar-select" aria-label="Dashboard theme" style="min-width:90px;padding:3px 6px">${['light','dark','midnight','packet'].map(t=>`<option ${S.theme===t?'selected':''}>${t}</option>`).join('')}</select><button class="icon-button" data-export-analysis title="Export analysis" aria-label="Export analysis">⇩</button><span class="avatar">MV</span></div></header><div class="titlebar"><div class="title-row"><div><h2>${S.view==='canvas'?'Drone delivery intelligence':S.view==='library'?'Research document library':S.view==='lineage'?'Source coverage & data lineage':datasetMeta(S.dataset).label}</h2><p>${S.view==='canvas'?'An editable analysis of markets, operators, approvals and property access.':S.view==='library'?'Official website articles, FAA documents and the supplied IBISWorld report.':'Trace every record to its source and distinguish statements from operating authority.'}</p></div><div class="actions">${S.view==='canvas'?`<button class="button" data-layout-dialog>◇ Save as layout</button><button class="button" data-toggle-edit>${S.edit?'✓ Editing':'Edit layout'}</button><button class="button primary" data-add-widget>＋ Add widget</button>`:`<button class="button" data-export-data>↓ Export records</button><button class="button primary" data-import>＋ Import data</button>`}</div></div>${S.view==='canvas'?`<nav class="tabs" aria-label="Analysis layouts">${Object.entries(boardNames).map(([k,n])=>`<button data-board="${k}" class="${S.board===k?'active':''}">${esc(n)}</button>`).join('')}<button class="add-layout" data-layout-dialog title="Create a saved layout">＋</button></nav>`:'<div style="height:14px"></div>'}</div><div class="filterbar"><label>SEARCH <input id="global-query" placeholder="Filter research records…" value="${esc(S.query)}"></label><label>COMPANY <select id="company-filter"><option>All companies</option>${['Wing','Amazon Prime Air','Zipline','Flytrex','DroneUp','Matternet','DEXA','DoorDash','FAA','IBISWorld'].map(c=>`<option ${S.company===c?'selected':''}>${c}</option>`).join('')}</select></label><label>EVIDENCE <select id="evidence-filter">${['All evidence','Regulator','Company','Partner statement','IBISWorld','Property','User import'].map(c=>`<option ${S.evidence===c?'selected':''}>${c}</option>`).join('')}</select></label><button class="button" data-reset-filters>Clear filters</button><span class="filter-spacer"></span><span class="subtle">Company filter applies to company object sets</span></div><div id="view-content"></div></main>`;renderContent()}
function renderContent(){if(S.view==='library')renderLibrary();else if(S.view==='datasets')renderDataset();else if(S.view==='lineage')renderLineage();else renderCanvas()}
function renderCanvas(){const widgets=S.layouts[S.board]||[];Q('#view-content').innerHTML=`<div class="analysis-info"><span>▦ <strong>${esc(boardNames[S.board])}</strong> · ${widgets.length} cards · ${S.edit?'Drag headers to reorder. Configure, duplicate or resize each card.':'Interactive view. Enable Edit layout to change cards.'}</span><span>Sources → object sets → visualizations</span></div><div class="metrics"><button class="metric" data-dataset="operators"><label>Operator profiles</label><strong>08</strong><small>7 in FAA history + DoorDash company announcement</small></button><button class="metric" data-nav="library"><label>Documents catalogued</label><strong>${dataFor('articles').length}</strong><small>${dataFor('articles').filter(r=>r.status==='Reviewed').length} reviewed · remainder indexed / linked</small></button><button class="metric" data-dataset="market"><label>2026 US food-delivery revenue</label><strong>$44.3B</strong><small>IBISWorld · general industry, not drone TAM</small></button><button class="metric" data-board="readiness"><label>Readiness task reviews</label><strong>${dataFor('regulations').filter(r=>r.status==='Review recorded').length}<span class="muted" style="font-size:14px"> / 12</span></strong><small>Planning evidence; not flight authorization</small></button></div><div class="canvas" id="canvas">${widgets.map(widgetHTML).join('')}${S.edit?'<button class="custom-cta" data-add-widget><b>＋</b>Create a custom widget<span class="subtle">Choose a dataset, chart and aggregation</span></button>':''}</div>`}
function widgetHTML(w){const m=datasetMeta(w.dataset),rows=rowsFor(w);return `<section class="widget" style="--span:${w.width||6}" data-widget-id="${w.id}" data-type="${w.type}"><header class="widget-header" ${S.edit?`draggable="true" data-drag-widget="${w.id}"`:''}><div class="widget-title">${S.edit?'<span class="drag-handle" title="Drag to reorder">⠿</span>':'<span class="muted">▧</span>'}<h3>${esc(w.title)}</h3></div><div class="widget-tools"><button data-widget-records="${w.id}" title="Inspect underlying records" aria-label="Inspect ${esc(w.title)}">↗</button>${S.edit?`<button data-edit-widget="${w.id}" title="Configure widget" aria-label="Configure ${esc(w.title)}">⚙</button><button data-duplicate="${w.id}" title="Duplicate widget" aria-label="Duplicate ${esc(w.title)}">⧉</button><button data-width="${w.id}" title="Cycle width: 4 / 6 / 8 / 12 columns" aria-label="Resize ${esc(w.title)}">↔</button><button data-move-up="${w.id}" title="Move card earlier" aria-label="Move ${esc(w.title)} earlier">↑</button><button data-remove-widget="${w.id}" title="Remove from layout" aria-label="Remove ${esc(w.title)}">×</button>`:''}</div></header><div class="widget-source"><span class="dot"></span>${esc(m.label)} <span> / </span>${rows.length} matching records</div><div class="widget-body">${visualize(w,rows)}${w.note?`<p class="widget-note">${esc(w.note)}</p>`:''}</div><footer class="widget-footer"><span>${esc(w.type)} · ${w.agg==='count'?'record count':esc(w.agg)+'('+esc(w.y)+')'}</span><button data-widget-records="${w.id}" style="font-size:9px;color:var(--accent)">View data & sources ↗</button></footer></section>`}
function visualize(w,rows){if(!rows.length)return '<div class="empty"><b>No matching records</b>Change the global filters or this widget’s filter.</div>';if(w.type==='table')return tableHTML(w.dataset,rows.slice(0,70),datasetMeta(w.dataset).fields);if(w.type==='list')return rows.slice(0,14).map(r=>`<button class="list-item" ${recordAttrs(w.dataset,r.id)}><strong>${esc(r.name||r.title||r.id)}</strong><small>${esc(r.company||r.category||'')} · ${esc(r.status||r.evidence||'Source record')}</small><p>${esc((r.summary||'').slice(0,220))}</p></button>`).join('');if(w.type==='graph')return graphHTML(w,rows);if(w.type==='timeline')return timelineHTML(w,rows);let groups=groupRows(w,rows);if(!groups.length)return '<div class="empty"><b>No numeric observations</b>Missing numeric data is not treated as zero. Select record count or another field.</div>';if(w.type==='stat'){let vals=groups.map(g=>g.value),n=w.agg==='avg'?vals.reduce((a,b)=>a+b,0)/vals.length:w.agg==='max'?Math.max(...vals):w.agg==='min'?Math.min(...vals):vals.reduce((a,b)=>a+b,0);return `<div class="stat-value">${fmt(n,w.y)}</div><div class="stat-label">${esc(w.agg==='count'?'Matching records':(labels[w.y]||w.y)+' · '+w.agg)}</div><div class="widget-note">${rows.length} source records. Inspect the widget to see the population.</div>`}if(w.type==='line')return lineHTML(w,groups);if(w.type==='donut')return donutHTML(w,groups);if(w.type==='scatter')return scatterHTML(w,rows);return barHTML(w,groups)}
function tableHTML(ds,rows,fields){return `<table class="data-table"><thead><tr>${fields.map(f=>`<th>${esc(labels[f]||f.replaceAll('_',' '))}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr tabindex="0" ${recordAttrs(ds,r.id)}>${fields.map((f,i)=>`<td class="${i===0?'cell-link':''}">${f==='status'?`<span class="tag ${r[f]==='Reviewed'?'reviewed':String(r[f]).includes('Design')?'planned':''}">${esc(r[f]||'Not recorded')}</span>`:esc(r[f]===null||r[f]===undefined||r[f]===''?'Not recorded':fmt(r[f],f))}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
function barHTML(w,groups){groups.sort((a,b)=>b.value-a.value);const max=Math.max(...groups.map(g=>Math.abs(g.value)),1);return groups.slice(0,18).map((g,i)=>`<button class="bar-row" data-group="${esc(w.id)}:${i}" data-group-key="${esc(g.key)}"><span>${esc(g.key)}${w.dataset==='capabilities'?`<small>${esc(g.records[0].status)}</small>`:''}</span><span class="track"><i style="width:${Math.abs(g.value)/max*100}%;background:${w.color||palette[i%palette.length]}"></i></span><strong>${fmt(g.value,w.y)}</strong></button>`).join('')+`<div class="legend"><span>${esc(w.agg==='count'?'Record count':labels[w.y]||w.y)} · select a bar for source records</span></div>`}
function lineHTML(w,groups){groups.sort((a,b)=>String(a.key).localeCompare(String(b.key),undefined,{numeric:true}));const chartWidth=Math.max(330,Math.round(((Q('.workspace')?.clientWidth||1000)-52)*(w.width||6)/12-30));let min=Math.min(0,...groups.map(g=>g.value)),max=Math.max(1,...groups.map(g=>g.value)),span=max-min,x=i=>44+(groups.length===1?(chartWidth-74)/2:i/(groups.length-1)*(chartWidth-74)),y=n=>177-(n-min)/span*145;return `<svg class="chart-svg" viewBox="0 0 ${chartWidth} 215" role="img" aria-label="${esc(w.title)}. ${groups.length} observations.">${[0,1,2,3].map(i=>{let v=min+span*i/3;return `<line class="gridline" x1="44" x2="${chartWidth-30}" y1="${y(v)}" y2="${y(v)}"/><text x="37" y="${y(v)+3}" text-anchor="end">${fmt(v,w.y)}</text>`}).join('')}${groups.slice(1).map((g,i)=>`<line x1="${x(i)}" y1="${y(groups[i].value)}" x2="${x(i+1)}" y2="${y(g.value)}" stroke="${w.color||'var(--blue)'}" stroke-width="2" ${g.records.some(r=>r.period==='Forecast')?'stroke-dasharray="4 3"':''}/>`).join('')}${groups.map((g,i)=>`<circle cx="${x(i)}" cy="${y(g.value)}" r="4" fill="${w.color||'var(--blue)'}" ${recordAttrs(w.dataset,g.records[0].id)} tabindex="0"><title>${esc(g.key)} · ${esc(labels[w.y]||w.y)}: ${fmt(g.value,w.y)}</title></circle>`).join('')}${[0,Math.floor((groups.length-1)/2),groups.length-1].filter((x,i,a)=>a.indexOf(x)===i).map(i=>`<text x="${x(i)}" y="201" text-anchor="middle">${esc(groups[i].key)}</text>`).join('')}</svg><div class="legend"><span><i></i>${esc(labels[w.y]||w.y)}</span>${w.dataset==='market'?'<span>Solid: report estimates</span><span>┄ Forecast after 2026</span>':''}<span>Click a point to inspect</span></div>`}
function donutHTML(w,groups){const valid=groups.filter(g=>g.value>0),total=valid.reduce((s,g)=>s+g.value,0);if(!total)return '<div class="empty">No positive values for a composition chart.</div>';let start=0;const gradient=valid.map((g,i)=>{let end=start+g.value/total*100,part=`${palette[i%palette.length]} ${start}% ${end}%`;start=end;return part}).join(',');return `<div class="donut-wrap"><div class="donut" style="background:conic-gradient(${gradient})"><div class="donut-center">${fmt(total,w.y)}<small>${w.y==='share'?'rounded share total':w.agg==='count'?'records':'total'}</small></div></div><div class="donut-legend">${valid.map((g,i)=>`<button data-group="${esc(w.id)}:${i}" data-group-key="${esc(g.key)}"><i style="background:${palette[i%palette.length]}"></i><span>${esc(g.key)}</span><b>${fmt(g.value,w.y)}${w.y==='share'?'%':''}</b></button>`).join('')}</div></div><p class="widget-note">${w.y==='share'?'Source percentages are retained; rounded totals can differ from 100%. ':'Composition of matching records. '}Select a legend item to inspect the underlying evidence.</p>`}
function timelineHTML(w,rows){const vals=rows.map(r=>typeof r[w.y]==='number'?r[w.y]:Number(String(r[w.y]||r.date||r.published||'').slice(0,4))).filter(Number.isFinite),min=Math.min(...vals),max=Math.max(...vals);if(!vals.length)return '<div class="empty">No dated numeric observations.</div>';return rows.filter(r=>r[w.y]!==null&&r[w.y]!==undefined).slice().sort((a,b)=>a[w.y]-b[w.y]).map(r=>`<button class="bar-row" ${recordAttrs(w.dataset,r.id)}><span>${esc(r[w.x]||r.name)}<small>${esc(r.holder||r.status||'')}</small></span><span class="track" style="height:1px;position:relative;overflow:visible"><i style="height:7px;width:7px;position:absolute;top:-3px;left:${max===min?50:(r[w.y]-min)/(max-min)*95}%;background:var(--blue)"></i></span><strong>${esc(r[w.y])}</strong></button>`).join('')+'<p class="widget-note">Historical dates, not approval for a current route. Inspect legal entity and milestone details.</p>'}
function graphHTML(w,rows){const graphWidth=Math.max(400,Math.round(((Q('.workspace')?.clientWidth||1000)-52)*(w.width||6)/12-30)),right=graphWidth-172;const a=[...new Set(rows.map(r=>r.company||r.name))].slice(0,8),b=[...new Set(rows.map(r=>r.partner||r.category))].filter(Boolean).slice(0,10),h=Math.max(a.length,b.length)*28+20,apos=new Map(a.map((n,i)=>[n,20+i*28])),bpos=new Map(b.map((n,i)=>[n,20+i*28]));return `<svg class="chart-svg" style="height:${Math.min(320,h)}px" viewBox="0 0 ${graphWidth} ${h}" role="img" aria-label="Company to partner relationship graph">${rows.filter(r=>apos.has(r.company)&&bpos.has(r.partner)).map(r=>`<path d="M172,${apos.get(r.company)} C${graphWidth*.45},${apos.get(r.company)} ${graphWidth*.55},${bpos.get(r.partner)} ${right},${bpos.get(r.partner)}" class="lineage-line" fill="none" ${recordAttrs(w.dataset,r.id)}><title>${esc(r.name)} · ${esc(r.status)}</title></path>`).join('')}${a.map(n=>`<g class="graph-node" ${recordAttrs(w.dataset,rows.find(r=>r.company===n||r.name===n).id)}><rect x="0" y="${apos.get(n)-10}" width="172" height="21" rx="2"/><text x="9" y="${apos.get(n)+3}">${esc(n.length>29?n.slice(0,27)+'…':n)}</text></g>`).join('')}${b.map(n=>`<g class="graph-node" ${recordAttrs(w.dataset,rows.find(r=>(r.partner||r.category)===n).id)}><rect x="${right}" y="${bpos.get(n)-10}" width="172" height="21" rx="2"/><text x="${right+9}" y="${bpos.get(n)+3}">${esc(n)}</text></g>`).join('')}</svg><p class="widget-note">Edges are sourced announcements, not active contracts or current operating availability. Select a node or edge.</p>`}
function scatterHTML(w,rows){let points=rows.filter(r=>typeof r[w.x]==='number'&&typeof r[w.y]==='number');if(!points.length)return '<div class="empty">Choose numeric X and Y fields for a scatter plot.</div>';let xmax=Math.max(1,...points.map(r=>r[w.x])),ymax=Math.max(1,...points.map(r=>r[w.y]));return `<svg class="chart-svg" viewBox="0 0 510 215" role="img" aria-label="${esc(w.title)}"><line class="gridline" x1="45" y1="180" x2="480" y2="180"/><line class="gridline" x1="45" y1="20" x2="45" y2="180"/>${points.map((r,i)=>`<circle cx="${45+r[w.x]/xmax*425}" cy="${180-r[w.y]/ymax*150}" r="6" fill="${palette[i%palette.length]}" ${recordAttrs(w.dataset,r.id)}><title>${esc(r.name)} · ${w.x}: ${r[w.x]} · ${w.y}: ${r[w.y]}</title></circle>`).join('')}<text x="250" y="208">${esc(labels[w.x]||w.x)}</text><text x="47" y="14">${esc(labels[w.y]||w.y)}</text></svg><div class="widget-note">Raw published values. Check units and range definitions before interpreting a relationship.</div>`}
function libraryRows(){let rows=rowsFor({dataset:'articles'});if(S.libraryStatus!=='All statuses')rows=rows.filter(r=>r.status===S.libraryStatus);if(S.libraryCategory!=='All topics')rows=rows.filter(r=>r.category===S.libraryCategory);return rows.sort((a,b)=>String(b.published||'').localeCompare(String(a.published||''))||a.title.localeCompare(b.title))}
function renderLibrary(){const rows=libraryRows(),size=24,pages=Math.max(1,Math.ceil(rows.length/size));S.libraryPage=Math.min(S.libraryPage,pages-1);const start=S.libraryPage*size;Q('#view-content').innerHTML=`<div class="content-page"><div class="library-info"><b>Catalogue scope:</b> public sitemaps and official source indexes reviewed on October 25, 2026. ${dataFor('articles').length} document records; ${dataFor('articles').filter(r=>r.status==='Reviewed').length} have reviewed research summaries. “Indexed” means page metadata was retrieved, not that all claims were validated. “Linked document” means an FAA PDF was discovered but not read in full. Flytrex’s public extraction is limited. This is a research snapshot, not a claim to include every page or attachment ever published.</div><div class="coverage-row">${['All companies','Wing','Amazon Prime Air','Zipline','Flytrex','DroneUp','Matternet','DEXA','DoorDash','FAA','IBISWorld'].map(c=>`<button data-company="${c}" class="${S.company===c?'active':''}">${c==='All companies'?'All sources':c} <span class="mono">${c==='All companies'?dataFor('articles').length:dataFor('articles').filter(r=>(r.company||'').includes(c)).length}</span></button>`).join('')}</div><div class="library-summary"><p><b style="color:var(--ink)">${rows.length}</b> matching documents · click any card for the quick view and original source.</p><div class="actions"><select id="library-status" class="toolbar-select" aria-label="Review status">${['All statuses','Reviewed','Indexed','Linked document','Link only'].map(t=>`<option ${S.libraryStatus===t?'selected':''}>${t}</option>`).join('')}</select><select id="library-category" class="toolbar-select" aria-label="Article topic">${['All topics','Operations','Partnerships','Certification','Environmental review'].map(t=>`<option ${S.libraryCategory===t?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="library-grid">${rows.slice(start,start+size).map(r=>`<button class="article-card" ${recordAttrs('articles',r.id)}><div class="publisher"><span>${esc(r.company)}</span><span>↗</span></div><h3>${esc(r.title)}</h3><p>${esc(r.summary||'Source metadata indexed; open the original article to review.')}</p><div class="article-meta"><span class="tag ${r.status==='Reviewed'?'reviewed':''}">${esc(r.status)}</span><span>${esc(r.published||'Date not recorded')}</span></div><div class="subtle" style="margin-top:9px;font-size:9px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(r.publisher||r.source_type)}</div></button>`).join('')||'<div class="empty">No documents match these filters.</div>'}</div><div class="pagination"><span>${rows.length?start+1:0}–${Math.min(start+size,rows.length)} of ${rows.length}</span><div class="actions"><button class="button" data-library-page="${S.libraryPage-1}" ${S.libraryPage===0?'disabled':''}>← Previous</button><span>Page ${S.libraryPage+1} / ${pages}</span><button class="button" data-library-page="${S.libraryPage+1}" ${S.libraryPage>=pages-1?'disabled':''}>Next →</button></div></div></div>`}
function renderDataset(){const ds=S.dataset,m=datasetMeta(ds),rows=rowsFor({dataset:ds});Q('#view-content').innerHTML=`<div class="content-page"><div class="dataset-summary"><div><span>OBJECT SET</span><b>${esc(m.label)}</b></div><div><span>Matching / total</span><b class="mono">${rows.length} / ${dataFor(ds).length}</b></div><div><span>Properties</span><b class="mono">${m.fields.length}</b></div><button class="button primary" style="margin-left:auto" data-create-from="${ds}">＋ Create widget from this data</button></div><div class="library-info">${esc(m.desc)}</div><div class="dataset-table-wrap">${tableHTML(ds,rows.slice(0,250),m.fields)}</div><p class="subtle" style="margin-top:10px">Showing up to 250 records. Filter to narrow the set or export all matching rows. Click a row to inspect source provenance.</p></div>`}
function renderLineage(){Q('#view-content').innerHTML=`<div class="content-page"><div class="library-info"><b>Research pipeline:</b> official websites, the FAA index and one user-provided IBISWorld PDF → structured research records → configurable cards. The financial workbook is excluded from the active application. The app does not automatically crawl new pages or extract arbitrary PDFs at runtime.</div><div class="canvas" style="padding:0"><section class="widget" style="--span:8"><div class="widget-header"><h3>Source-to-analysis lineage</h3></div><div class="widget-body"><svg class="chart-svg" viewBox="0 0 650 245" role="img" aria-label="Research sources connect to structured datasets and widgets"><g fill="none" stroke="var(--border)">${[40,100,160,220].map(y=>`<path d="M190 ${y}C250 ${y}230 120 290 120"/>`).join('')}<path d="M455 120C490 120 490 70 520 70"/><path d="M455 120C490 120 490 170 520 170"/></g>${[['Official competitor sites',15,25,175],['FAA & local agencies',15,85,175],['IBISWorld OD6309 PDF',15,145,175],['User CSV / JSON imports',15,205,175],['Typed object sets',290,103,165],['Custom widgets',520,53,120],['Source inspector',520,153,120]].map(([t,x,y,width])=>`<rect x="${x}" y="${y}" width="${width}" height="32" rx="3" fill="var(--chrome)" stroke="var(--border)"/><text x="${x+10}" y="${y+20}" style="font-size:11px;fill:var(--ink)">${t}</text>`).join('')}</svg></div></section><section class="widget" style="--span:4"><div class="widget-header"><h3>Evidence semantics</h3></div><div class="widget-body"><div class="field"><label>Regulator</label><div>Official guidance and historical certification records; route-specific authority still requires applicable approvals.</div></div><div class="field"><label>Company / partner statement</label><div>Reported capabilities, partnerships or future plans. Claims are dated and scoped to the relevant system.</div></div><div class="field"><label>IBISWorld</label><div>US food delivery industry context. No drone TAM or drone operating costs inferred.</div></div><div class="field"><label>Indexed vs reviewed</label><div>Metadata discovery and substantive review are tracked separately. PDF links are not presented as reviewed text.</div></div></div></section><section class="widget" style="--span:8"><div class="widget-header"><h3>Website coverage and access limits</h3></div><div class="widget-body">${tableHTML('coverage',dataFor('coverage'),['name','records','reviewed','status'])}</div></section><section class="widget" style="--span:4"><div class="widget-header"><h3>Portable research workspace</h3></div><div class="widget-body"><p class="subtle">Layouts, imported datasets, notes and evidence reviews are browser-local. Export analysis to move or back up this workspace.</p><button class="button" data-export-analysis style="margin-top:15px">↓ Export analysis JSON</button><button class="button" data-import style="margin-top:9px">↑ Import data / analysis</button><div class="widget-note">The free, self-hosted Metabase edition is an alternative for structured CSV/database dashboards. PDF and website prose must first be extracted into source-linked tables.</div><a href="https://www.metabase.com/start/oss" target="_blank" rel="noopener" style="font-size:11px;display:block;margin-top:12px">Metabase open-source edition ↗</a></div></section></div></div>`}
function inspectRecord(ds,id){const r=dataFor(ds).find(r=>String(r.id)===String(id));if(!r)return;const u=safeUrl(r.source_url||r.url),m=datasetMeta(ds),related=dataFor('articles').filter(a=>r.source_url&&safeUrl(a.source_url)===safeUrl(r.source_url)).slice(0,4);openInspector(r.name||r.title||r.id,`<span class="tag">${esc(m.label)}</span><div class="source-box"><b>${esc(r.source_type||'Research record')}</b><br>${esc(r.locator||r.evidence||r.publisher||'Source metadata available below')}<br>${u?`<a href="${esc(u)}" target="_blank" rel="noopener">Open original source ↗</a>`:'User-provided report / structured data; no public source URL.'}${r.date||r.published?`<br>Publication / statement date: ${esc(r.date||r.published)}`:''}<br>Research snapshot: ${esc(r.retrieval||(['permits','properties','sources'].includes(ds)?'2026-10-26':'2026-10-25'))}</div>${Object.entries(r).filter(([k,v])=>!['id','name','title','source_url','url','source_type','publisher','retrieval','index','reviewed_at'].includes(k)&&v!==''&&v!==null&&v!==undefined).map(([k,v])=>`<div class="field"><label>${esc(labels[k]||k.replaceAll('_',' '))}</label><div>${/^https?:/.test(String(v))&&safeUrl(v)?`<a href="${esc(safeUrl(v))}" target="_blank" rel="noopener">${esc(v)} ↗</a>`:esc(typeof v==='object'?JSON.stringify(v):v)}</div></div>`).join('')}${ds==='regulations'?`<label class="check-action"><input type="checkbox" data-check="${r.index}" ${S.checks[r.index]?'checked':''}> Evidence review recorded for this planning task</label><p class="subtle">A recorded review does not grant permission to fly.</p>`:''}<h3>Private research notes</h3><textarea id="record-note" data-note-key="${esc(ds+':'+id)}" placeholder="Evidence references, questions and next actions…">${esc(S.notes[ds+':'+id]||'')}</textarea><p class="subtle">Notes save in this browser. Export analysis for backup.</p>${related.length&&ds!=='articles'?`<h3>Linked catalogue records</h3>${related.map(a=>`<button class="list-item" ${recordAttrs('articles',a.id)}><strong>${esc(a.title)}</strong><small>${esc(a.status)}</small></button>`).join('')}`:''}`)}
function openInspector(title,html){lastFocus=document.activeElement;Q('#inspector').innerHTML=`<div class="inspector-header"><span>OBJECT INSPECTOR</span><button class="icon-button" data-close-inspector aria-label="Close inspector">×</button></div><div class="inspector-scroll"><h2>${esc(title)}</h2>${html}</div>`;Q('#inspector').inert=false;Q('#inspector').classList.add('open');Q('[data-close-inspector]').focus()}
function closeInspector(){Q('#inspector').inert=true;Q('#inspector').classList.remove('open');lastFocus?.isConnected&&lastFocus.focus()}
function inspectRows(w,rs){openInspector(w.title,`<div class="source-box">${esc(datasetMeta(w.dataset).desc)}<br><b>${rs.length}</b> matching records · ${esc(w.agg)}(${esc(w.y)})${w.filter?'<br>Widget filter: '+esc(w.filter):''}</div><div style="overflow:auto">${tableHTML(w.dataset,rs.slice(0,120),datasetMeta(w.dataset).fields)}</div><p class="subtle" style="margin-top:12px">Select a row to open its complete source record.</p>`)}
function currentWidgets(){return S.layouts[S.board]||[]}
function findWidget(id){return currentWidgets().find(w=>w.id===id)}
function newId(){return 'w'+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
function openBuilder(id=null,ds=null){editId=id;const existing=id?findWidget(id):null;draft=existing?structuredClone(existing):{id:newId(),title:'New research widget',dataset:ds||'operators',type:'bar',x:ds==='market'?'year':ds==='articles'?'company':'focus',y:ds==='market'?'revenue':'count',agg:ds==='market'?'sum':'count',width:6,filter:''};if(!datasetMeta(draft.dataset).fields.includes(draft.x))draft.x=datasetMeta(draft.dataset).fields[0];renderBuilder();Q('#builder').showModal()}
function renderBuilder(){const m=datasetMeta(draft.dataset),fields=m.fields;Q('#builder').innerHTML=`<div class="modal-head"><h2>${editId?'Configure widget':'Create custom widget'}</h2><button data-close-builder class="icon-button" aria-label="Close widget builder">×</button></div><div class="builder-grid"><form class="builder-form" id="widget-form"><label class="form-label" for="widget-title">Widget title</label><input id="widget-title" class="form-control" value="${esc(draft.title)}" required><label class="form-label" for="widget-dataset">Input object set</label><select id="widget-dataset" class="form-control">${Object.keys(allData()).map(k=>`<option value="${k}" ${draft.dataset===k?'selected':''}>${esc(datasetMeta(k).label)} (${dataFor(k).length})</option>`).join('')}</select><label class="form-label" for="widget-type">Visualization</label><select id="widget-type" class="form-control">${[['bar','Horizontal bars'],['line','Line chart'],['donut','Composition / donut'],['table','Object table'],['list','Article / record list'],['stat','Metric'],['timeline','Milestone timeline'],['graph','Relationship graph'],['scatter','Numeric scatter plot']].map(([k,l])=>`<option value="${k}" ${draft.type===k?'selected':''} ${k==='graph'&&draft.dataset!=='relationships'?'disabled':''}>${l}</option>`).join('')}</select><div class="form-row"><div><label class="form-label" for="widget-x">Group / X property</label><select id="widget-x" class="form-control">${fields.map(f=>`<option ${draft.x===f?'selected':''} value="${f}">${esc(labels[f]||f)}</option>`).join('')}</select></div><div><label class="form-label" for="widget-y">Measure / Y property</label><select id="widget-y" class="form-control"><option value="count" ${draft.y==='count'?'selected':''}>Record count</option>${m.numeric.map(f=>`<option ${draft.y===f?'selected':''} value="${f}">${esc(labels[f]||f)}</option>`).join('')}</select></div></div><div class="form-row"><div><label class="form-label" for="widget-agg">Aggregation</label><select id="widget-agg" class="form-control">${['count','sum','avg','min','max'].map(t=>`<option ${draft.agg===t?'selected':''}>${t}</option>`).join('')}</select></div><div><label class="form-label" for="widget-width">Card width</label><select id="widget-width" class="form-control">${[[4,'⅓ canvas'],[6,'½ canvas'],[8,'⅔ canvas'],[12,'Full canvas']].map(([v,l])=>`<option value="${v}" ${draft.width===v?'selected':''}>${l}</option>`).join('')}</select></div></div><label class="form-label" for="widget-filter">Widget-level record filter (contains text)</label><input id="widget-filter" class="form-control" value="${esc(draft.filter||'')}" placeholder="e.g. Reviewed, Wing, Service mix"><label class="form-label" for="widget-note">Context / interpretation</label><textarea id="widget-note" class="form-control" placeholder="State units, scope or an important caveat.">${esc(draft.note||'')}</textarea><div class="form-help">Global filters also apply. Missing numeric values remain unavailable. Design claims must remain distinguished from current operations.</div><div id="builder-error" class="error"></div></form><div class="builder-preview"><h3>LIVE PREVIEW</h3><div class="widget" style="--span:12"><header class="widget-header"><h3 id="preview-title">${esc(draft.title)}</h3></header><div class="widget-source">${esc(m.label)}</div><div class="widget-body" id="widget-preview"></div></div><p class="form-help" style="margin-top:12px">Input → filter → ${esc(draft.agg)} → ${esc(draft.type)}. This card uses source records, not generated estimates.</p></div></div><div class="modal-foot"><span class="subtle">${rowsFor(draft).length} matching input records</span><div class="actions"><button class="button" data-close-builder>Cancel</button><button class="button primary" data-save-widget>${editId?'Apply changes':'Add to canvas'}</button></div></div>`;updatePreview()}
function updatePreview(){if(!draft)return;Q('#preview-title').textContent=draft.title;Q('#widget-preview').innerHTML=visualize(draft,rowsFor(draft));}
function saveWidget(){if(!draft.title.trim()){Q('#builder-error').textContent='Enter a widget title.';return}if(draft.type==='scatter'&&(!datasetMeta(draft.dataset).numeric.includes(draft.x)||!datasetMeta(draft.dataset).numeric.includes(draft.y))){Q('#builder-error').textContent='Scatter plots require numeric X and Y properties.';return}if(draft.type==='timeline'&&!datasetMeta(draft.dataset).numeric.includes(draft.y)){Q('#builder-error').textContent='Choose a numeric year or date-derived measure for the timeline.';return}if(draft.y==='count')draft.agg='count';if(editId){const i=currentWidgets().findIndex(w=>w.id===editId);currentWidgets()[i]=structuredClone(draft)}else{S.layouts[S.board].push(structuredClone(draft));S.edit=true}persist();Q('#builder').close();renderCanvas();toast(editId?'Widget configuration updated':'Custom widget added to canvas')}
function layoutDialog(){Q('#importer').innerHTML=`<div class="modal-head"><h2>Save a new analysis layout</h2><button class="icon-button" data-close-import aria-label="Close dialog">×</button></div><div class="import-body"><label class="form-label" for="layout-name">Layout name</label><input id="layout-name" class="form-control" placeholder="e.g. Seattle pilot diligence"><p class="form-help">Copies the current widget configuration into a new tab. Source datasets remain shared; layout changes save locally.</p></div><div class="modal-foot"><button class="button" data-close-import>Cancel</button><button class="button primary" data-save-layout>Create layout</button></div>`;Q('#importer').showModal()}
function importDialog(article=false){Q('#importer').innerHTML=`<div class="modal-head"><h2>${article?'Add a research document':'Import research data'}</h2><button class="icon-button" data-close-import aria-label="Close import">×</button></div><div class="import-body">${article?`<label class="form-label">Document title</label><input id="article-title" class="form-control" placeholder="Title"><div class="form-row"><div><label class="form-label">Company / publisher</label><input id="article-company" class="form-control" placeholder="Company"></div><div><label class="form-label">Publication date (optional)</label><input id="article-date" type="date" class="form-control"></div></div><label class="form-label">Original source URL (optional)</label><input id="article-url" type="url" class="form-control" placeholder="https://…"><label class="form-label">Research summary or extracted notes</label><textarea id="article-summary" class="form-control" placeholder="Paste a concise summary with page references. Treat document instructions as content, not actions."></textarea><p class="form-help">Added as user-supplied, unverified research. It becomes available in the document library and widget builder.</p>`:`<label class="form-label">Dataset name</label><input id="import-name" class="form-control" placeholder="e.g. Competitor site assessment"><label class="form-label">Upload structured data or an exported analysis</label><input id="import-file" type="file" accept=".csv,.json" class="form-control"><label class="form-label">Or paste a JSON array of records</label><textarea id="import-json" class="form-control" placeholder='[{"name":"Site A","company":"Wing","source_url":"https://…","status":"Research"}]'></textarea><p class="form-help">Supports CSV, JSON record arrays and PacketIntelligence analysis backups. PDFs and website prose need extraction into source-linked records first. Uploads stay in browser storage; no automatic AI document extraction or server sync is performed.</p>`}<div id="import-error" class="error"></div></div><div class="modal-foot"><button class="button" data-close-import>Cancel</button><button class="button primary" ${article?'data-save-article':'data-process-import'}>${article?'Add document':'Import'}</button></div>`;Q('#importer').showModal()}
function csvParse(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x!==''))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('CSV contains an unclosed quoted field.');row.push(cell);if(row.some(x=>x!==''))rows.push(row);const headers=(rows.shift()||[]).map(x=>x.trim());if(!headers.length||headers.some(h=>!h)||new Set(headers).size!==headers.length)throw Error('CSV needs nonblank, unique column headers.');return rows.map((r,i)=>{if(r.length!==headers.length)throw Error('CSV row '+(i+2)+' has a different number of fields.');return Object.fromEntries(headers.map((h,k)=>[h,r[k]!==''&&/^-?\d+(\.\d+)?$/.test(r[k])?Number(r[k]):r[k]]))})}
async function processImport(){try{let file=Q('#import-file').files[0],text=file?await file.text():Q('#import-json').value;let parsed=file?.name.toLowerCase().endsWith('.csv')?csvParse(text):JSON.parse(text);if(Array.isArray(parsed?.records))parsed=parsed.records;if(parsed?.format==='packet-research-v3'&&parsed.state){let incoming=parsed.state;if(!incoming.layouts||typeof incoming.layouts!=='object')throw Error('Analysis backup has no valid layouts.');for(const [k,v]of Object.entries(incoming.layouts)){if(!Array.isArray(v)||v.some(w=>!w.dataset||!w.type||!w.id))throw Error('Invalid widget configuration in backup.')}S.layouts=incoming.layouts;S.imports=incoming.imports||{};S.importNames=incoming.importNames||{};S.notes=incoming.notes||{};S.checks=incoming.checks||{};Object.assign(boardNames,incoming.boardNames||{});S.board=Object.keys(S.layouts)[0];persist();Q('#importer').close();shell();toast('Analysis backup imported');return}if(!Array.isArray(parsed)||!parsed.length||parsed.some(r=>!r||typeof r!=='object'||Array.isArray(r)))throw Error('Use a nonempty JSON array of objects or a CSV table.');if(parsed.length>20000)throw Error('This browser-local workspace supports up to 20,000 rows per imported dataset.');if(parsed.some(r=>Object.keys(r).some(k=>['__proto__','constructor','prototype'].includes(k))))throw Error('Remove reserved property names from the import.');const key='import_'+Date.now().toString(36),name=Q('#import-name').value.trim()||file?.name||'Imported research';S.imports[key]=parsed.map((r,i)=>({...r,id:'i'+i,name:r.name||r.title||'Record '+(i+1),source_type:'User import',locator:r.locator||name,source_url:safeUrl(r.source_url||r.url||'')}));S.importNames??={};S.importNames[key]=name;S.dataset=key;S.view='datasets';persist();Q('#importer').close();shell();toast(parsed.length+' records imported. Create a widget from this dataset.')}catch(e){Q('#import-error').textContent=e.message}}
function saveArticle(){let title=Q('#article-title').value.trim(),summary=Q('#article-summary').value.trim();if(!title||!summary){Q('#import-error').textContent='A title and research summary are required.';return}let url=Q('#article-url').value.trim();if(url&&!safeUrl(url)){Q('#import-error').textContent='Use an http or https source URL.';return}const r={id:'user'+Date.now().toString(36),name:title,title,company:Q('#article-company').value.trim()||'User research',published:Q('#article-date').value,source_url:url,url,summary,status:'User supplied',source_type:'User import',category:'Operations',evidence:'Unverified user research',publisher:url?new URL(url).hostname:'User-provided document'};S.imports.articles??=structuredClone(researchData.articles);S.imports.articles.push(r);S.view='library';S.query='';S.company='All companies';S.evidence='All evidence';S.libraryStatus='All statuses';S.libraryPage=0;persist();Q('#importer').close();shell();toast('Document added to research library')}
function download(name,content,type='application/json'){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();URL.revokeObjectURL(u)}
function exportAnalysis(){download('packetintelligence-analysis.json',JSON.stringify({format:'packet-research-v3',exported_at:new Date().toISOString(),research_snapshot:'2026-10-25',state:{layouts:S.layouts,boardNames,imports:S.imports,importNames:S.importNames,notes:S.notes,checks:S.checks,theme:S.theme}},null,2));toast('Analysis exported, including layouts and local research notes')}
function exportData(){let ds=S.view==='library'?'articles':S.dataset;const rs=S.view==='library'?libraryRows():rowsFor({dataset:ds});download('packetintelligence-'+ds+'.json',JSON.stringify({dataset:ds,source_snapshot:'2026-10-25',records:rs},null,2))}
function widgetFromForm(target){if(!draft)return;const map={'widget-title':'title','widget-type':'type','widget-x':'x','widget-y':'y','widget-agg':'agg','widget-width':'width','widget-filter':'filter','widget-note':'note'};if(target.id==='widget-dataset'){draft.dataset=target.value;const m=datasetMeta(draft.dataset);draft.x=m.fields[0];draft.y='count';draft.agg='count';if(draft.type==='graph'&&draft.dataset!=='relationships')draft.type='bar';renderBuilder();return}if(map[target.id]){draft[map[target.id]]=target.id==='widget-width'?+target.value:target.value;if(target.id==='widget-y'){draft.agg=target.value==='count'?'count':'sum';Q('#widget-agg').value=draft.agg}updatePreview()}}
document.addEventListener('click',e=>{const rec=e.target.closest('[data-record]');if(rec){const [ds,id]=rec.dataset.record.split(':');inspectRecord(ds,id);return}const t=e.target.closest('button');if(!t)return;
if(t.dataset.nav){S.view=t.dataset.nav;persist();shell()}
if(t.hasAttribute('data-toggle-sidebar')){S.collapsed=!S.collapsed;persist();shell()}
if(t.dataset.theme){S.theme=t.dataset.theme;persist();shell()}
if(t.dataset.dataset){S.dataset=t.dataset.dataset;S.view='datasets';persist();shell()}
if(t.dataset.board){S.board=t.dataset.board;S.view='canvas';persist();shell()}
if(t.hasAttribute('data-add-widget'))openBuilder();if(t.dataset.createFrom)openBuilder(null,t.dataset.createFrom);if(t.dataset.editWidget)openBuilder(t.dataset.editWidget);
if(t.hasAttribute('data-close-builder'))Q('#builder').close();if(t.hasAttribute('data-save-widget'))saveWidget();
if(t.hasAttribute('data-layout-dialog'))layoutDialog();if(t.hasAttribute('data-save-layout')){const name=Q('#layout-name').value.trim();if(!name){Q('#layout-name').focus();return}let id='board'+Date.now().toString(36);boardNames[id]=name;S.layouts[id]=structuredClone(currentWidgets()).map(w=>({...w,id:newId()}));S.board=id;persist();Q('#importer').close();shell();toast('New layout saved in this browser')}
if(t.hasAttribute('data-toggle-edit')){S.edit=!S.edit;persist();shell()}
if(t.dataset.duplicate){const w=findWidget(t.dataset.duplicate);if(w){const i=currentWidgets().indexOf(w);currentWidgets().splice(i+1,0,{...structuredClone(w),id:newId(),title:w.title+' · copy'});persist();renderCanvas();toast('Card duplicated')}}
if(t.dataset.width){const w=findWidget(t.dataset.width);if(w){const widths=[4,6,8,12];w.width=widths[(widths.indexOf(w.width)+1)%4];persist();renderCanvas()}}
if(t.dataset.moveUp){const i=currentWidgets().findIndex(w=>w.id===t.dataset.moveUp);if(i>0){const ws=currentWidgets();[ws[i-1],ws[i]]=[ws[i],ws[i-1]];persist();renderCanvas()}}
if(t.dataset.removeWidget){S.layouts[S.board]=currentWidgets().filter(w=>w.id!==t.dataset.removeWidget);persist();renderCanvas();toast('Card removed from layout. Its source data is retained.')}
if(t.dataset.widgetRecords){const w=findWidget(t.dataset.widgetRecords);if(w)inspectRows(w,rowsFor(w))}
if(t.dataset.group){const id=t.dataset.group.split(':')[0],w=findWidget(id);if(w){const rs=rowsFor(w).filter(r=>String(r[w.x]??'Not recorded')===t.dataset.groupKey);if(rs.length===1)inspectRecord(w.dataset,rs[0].id);else inspectRows({...w,title:w.title+' · '+t.dataset.groupKey},rs)}}
if(t.hasAttribute('data-close-inspector'))closeInspector();
if(t.hasAttribute('data-reset-filters')){S.query='';S.company='All companies';S.evidence='All evidence';S.libraryStatus='All statuses';S.libraryCategory='All topics';S.libraryPage=0;persist();shell()}
if(t.dataset.company){S.company=t.dataset.company;S.libraryPage=0;persist();shell()}
if(t.dataset.libraryPage!==undefined){S.libraryPage=+t.dataset.libraryPage;persist();renderLibrary();Q('.content-page').scrollIntoView({block:'start'})}
if(t.hasAttribute('data-import'))importDialog();if(t.hasAttribute('data-add-article'))importDialog(true);if(t.hasAttribute('data-close-import'))Q('#importer').close();if(t.hasAttribute('data-process-import'))processImport();if(t.hasAttribute('data-save-article'))saveArticle();if(t.hasAttribute('data-export-analysis'))exportAnalysis();if(t.hasAttribute('data-export-data'))exportData();});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='global-query'){S.query=t.value;S.libraryPage=0;persist();renderContent()}if(t.dataset.noteKey){S.notes[t.dataset.noteKey]=t.value;persist()}if(t.closest('#widget-form'))widgetFromForm(t)});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='theme-select'){S.theme=t.value;persist();shell()}if(t.id==='company-filter'){S.company=t.value;S.libraryPage=0;persist();renderContent()}if(t.id==='evidence-filter'){S.evidence=t.value;S.libraryPage=0;persist();renderContent()}if(t.id==='library-status'){S.libraryStatus=t.value;S.libraryPage=0;persist();renderLibrary()}if(t.id==='library-category'){S.libraryCategory=t.value;S.libraryPage=0;persist();renderLibrary()}if(t.dataset.check!==undefined){S.checks[t.dataset.check]=t.checked;persist();renderContent();toast('Planning evidence review updated')}if(t.closest('#widget-form'))widgetFromForm(t)});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeInspector();const t=e.target.closest('[data-record]');if(t&&(e.key==='Enter'||e.key===' ')){e.preventDefault();const [ds,id]=t.dataset.record.split(':');inspectRecord(ds,id)}});
document.addEventListener('dragstart',e=>{const h=e.target.closest('[data-drag-widget]'),d=e.target.closest('[data-drag-dataset]');if(h){dragId=h.dataset.dragWidget;e.dataTransfer.setData('text/plain','widget:'+dragId);e.dataTransfer.effectAllowed='move';h.closest('.widget').classList.add('dragging')}if(d){e.dataTransfer.setData('text/plain','dataset:'+d.dataset.dragDataset);e.dataTransfer.effectAllowed='copy'}});
document.addEventListener('dragover',e=>{if(e.target.closest('#canvas')){e.preventDefault();const w=e.target.closest('.widget');document.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'));w?.classList.add('drop-target')}});
document.addEventListener('drop',e=>{if(!e.target.closest('#canvas'))return;e.preventDefault();const text=e.dataTransfer.getData('text/plain'),target=e.target.closest('[data-widget-id]');document.querySelectorAll('.drop-target,.dragging').forEach(el=>el.classList.remove('drop-target','dragging'));if(text.startsWith('dataset:')){openBuilder(null,text.slice(8));return}if(text.startsWith('widget:')&&target){const id=text.slice(7),ws=currentWidgets(),from=ws.findIndex(w=>w.id===id),to=ws.findIndex(w=>w.id===target.dataset.widgetId);if(from>=0&&to>=0&&from!==to){const[w]=ws.splice(from,1);ws.splice(to,0,w);persist();renderCanvas();toast('Card order updated')}}});
document.addEventListener('dragend',()=>document.querySelectorAll('.drop-target,.dragging').forEach(el=>el.classList.remove('drop-target','dragging')));
Q('#builder').addEventListener('submit',e=>{e.preventDefault();saveWidget()});
shell();
